#include <cstdio>
#include <array>
#include <vector>

const int kMaxSquare = 64;
const int kMaxValue = 1000; // Assuming a reasonable max value for the board state
int roulette[4];

typedef struct {
    int type;
    int value;
} BoardState;

BoardState board[kMaxSquare];

int bp(int X, int Y) {
    std::vector<std::vector<double>> bp(Y + 1, std::vector<double>(kMaxValue, 0.0));
    double prob = 1.0 / static_cast<double>(X);
    bp[0][0] = 1.0;

    for (int n = 0; n < Y; n++) {
        for (int j = 0; j < kMaxValue; j++) {
            if (bp[n][j] > 0) {
                for (int k = 0; k < X; k++) {
                    int pos = (n + roulette[k] < Y) ? n + roulette[k] : Y;

                    if (board[pos].type == 1)
                        bp[(pos + board[pos].value < Y) ? pos + board[pos].value : Y][j]
                            += bp[n][j] * prob;
                    else if (board[pos].type == 2)
                        bp[pos][j + board[pos].value] += bp[n][j] * prob;
                    else if (board[pos].type == 3)
                        bp[pos][(j - board[pos].value > 0) ? j - board[pos].value : 0]
                            += bp[n][j] * prob;
                    else
                        bp[pos][j] += bp[n][j] * prob;
                }
            }
        }
    }

    double res = 0.0;
    for (int j = 0; j < kMaxValue; j++)
        res += static_cast<double>(j) * bp[Y][j];

    return static_cast<int>(res);
}

int main() {
    while (true) {
        int X, Y, Z;
        scanf("%d %d %d", &X, &Y, &Z);
        if (X == 0) return 0;

        for (int i = 0; i < X; i++)
            scanf("%d", &roulette[i]);

        for (int i = 0; i < kMaxSquare; i++)
            board[i] = {0, 0};

        for (; Z > 0; Z--) {
            int N, E, A;
            scanf("%d %d %d", &N, &E, &A);
            board[N] = {E, A};
        }

        printf("%d\n", bp(X, Y));
    }
}

